-- The diagnostic revision is independent so an active pre-test never delays practice/post-test fixes.
LOCK TABLE public.assessment_sessions IN SHARE ROW EXCLUSIVE MODE;
DO $$
BEGIN
 IF EXISTS (SELECT 1 FROM public.assessment_sessions s JOIN public.assessments a ON a.id=s.assessment_id
  WHERE a.slug='pre-test-basis-data' AND s.status='IN_PROGRESS') THEN
  RAISE EXCEPTION 'Finish active pre-tests before revising diagnostic questions';
 END IF;
 IF (SELECT count(*) FROM public.assessment_items i JOIN public.assessments a ON a.id=i.assessment_id WHERE a.slug='pre-test-basis-data') <> 10 THEN
  RAISE EXCEPTION 'Expected ten diagnostic items';
 END IF;
END $$;
WITH revisions AS (SELECT * FROM jsonb_to_recordset($questions$[{"slug":"pre-test-basis-data","position":1,"title":"Membaca kolom katalog","prompt":"Petugas perpustakaan menyimpan daftar buku pada tabel `books` di bawah. Setiap baris mewakili satu buku, sedangkan judul kolom menyatakan atributnya.\n\nManakah yang merupakan **nama kolom** pada tabel tersebut?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"title"},{"id":"b","text":"Dasar Basis Data"},{"id":"c","text":"5"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":2,"title":"Identitas mahasiswa","prompt":"Bagian akademik menyimpan mahasiswa pada tabel `students`. Mahasiswa yang berbeda boleh memiliki nama dan angkatan yang sama. Setiap `student_id` diberikan kepada satu mahasiswa dan tidak boleh kosong.\n\nKolom mana yang tepat digunakan untuk membedakan setiap record mahasiswa?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"name"},{"id":"b","text":"student_id"},{"id":"c","text":"cohort"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"campus","tables":["students"],"relations":false}}},{"slug":"pre-test-basis-data","position":3,"title":"Rujukan buku ke penulis","prompt":"Perpustakaan menyimpan buku dan penulis pada dua tabel terpisah. Nilai `books.author_id` harus merujuk `authors.author_id` yang sudah ada.\n\nApa tujuan rujukan tersebut ketika sebuah buku dicatat?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"Menentukan urutan judul buku di katalog."},{"id":"b","text":"Menghitung jumlah stok setiap buku."},{"id":"c","text":"Menghubungkan buku dengan record penulisnya."},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["authors","books"],"relations":false}}},{"slug":"pre-test-basis-data","position":4,"title":"Daftar judul untuk pengunjung","prompt":"Petugas ingin menyiapkan daftar yang hanya berisi judul buku dari tabel `books`. Kolom lain tidak diperlukan dan data asli tidak boleh berubah.\n\nQuery mana yang menghasilkan daftar tersebut?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"SELECT title FROM books;"},{"id":"b","text":"SELECT stock FROM books;"},{"id":"c","text":"SELECT * FROM books;"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":5,"title":"Memilih buku dengan stok cukup","prompt":"Perpustakaan menyiapkan daftar buku untuk kegiatan membaca bersama. Hanya buku dengan stok **lebih dari 2** yang boleh dipilih.\n\nJika kondisi query adalah `WHERE stock > 2`, pasangan judul mana yang masuk hasil berdasarkan data di bawah?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"Dasar Basis Data dan Pengantar SQL"},{"id":"b","text":"Dasar Basis Data dan Algoritma Ringkas"},{"id":"c","text":"Algoritma Ringkas dan Pengantar SQL"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":6,"title":"Laporan buku dan penulis","prompt":"Petugas membutuhkan judul buku bersama nama penulisnya. Informasi judul berada di `books`, sedangkan nama penulis berada di `authors`. `books.author_id` menyimpan rujukan penulis.\n\nPasangan kolom mana yang harus dicocokkan saat menghubungkan kedua tabel?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"books.title = authors.name"},{"id":"b","text":"books.book_id = authors.author_id"},{"id":"c","text":"books.author_id = authors.author_id"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["authors","books"],"relations":false}}},{"slug":"pre-test-basis-data","position":7,"title":"Menghitung judul terdaftar","prompt":"Petugas ingin mengetahui banyaknya record buku dalam katalog, bukan total eksemplar stok. Setiap baris tabel `books` mewakili satu judul terdaftar.\n\nBerapa hasil query berikut berdasarkan seluruh data tabel?\n\n```sql\nSELECT COUNT(*) FROM books;\n```","publicConfig":{"mode":"choice","options":[{"id":"a","text":"4"},{"id":"b","text":"10"},{"id":"c","text":"3"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":8,"title":"Mencatat buku baru","prompt":"Perpustakaan menerima satu judul baru yang belum tercatat. Petugas ingin menambahkan satu record ke tabel `books` dan mempertahankan seluruh record sebelumnya.\n\nPerintah SQL apa yang digunakan untuk kebutuhan tersebut?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"UPDATE"},{"id":"b","text":"INSERT INTO"},{"id":"c","text":"SELECT"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":9,"title":"Memperbarui stok satu buku","prompt":"Setelah menerima tambahan eksemplar, stok buku dengan `book_id = 30` harus menjadi **4**. Stok buku lain tidak boleh berubah.\n\nQuery mana yang memperbarui hanya record yang dimaksud?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"UPDATE books SET stock = 4;"},{"id":"b","text":"UPDATE books SET stock = 4 WHERE author_id = 1;"},{"id":"c","text":"UPDATE books SET stock = 4 WHERE book_id = 30;"},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books"],"relations":false}}},{"slug":"pre-test-basis-data","position":10,"title":"Menghapus record secara terarah","prompt":"Buku dengan `book_id = 20` akan dikeluarkan dari katalog. Petugas perlu memastikan bahwa hanya buku tersebut yang dihapus dan data penulis tetap ada.\n\nApa langkah yang tepat **sebelum** menjalankan DELETE?","publicConfig":{"mode":"choice","options":[{"id":"a","text":"Periksa record dengan SELECT dan WHERE book_id = 20, lalu gunakan kondisi yang sama untuk DELETE."},{"id":"b","text":"Periksa semua buku, lalu jalankan DELETE FROM books tanpa WHERE."},{"id":"c","text":"Periksa penulis buku, lalu hapus record penulisnya."},{"id":"unknown","text":"Belum tahu"}],"data":{"datasetId":"library","tables":["books","authors"],"relations":false}}}]$questions$::jsonb)
 AS r(slug text, position integer, title text, prompt text, "publicConfig" jsonb))
UPDATE public.assessment_items i SET title=r.title,prompt=r.prompt,public_config=r."publicConfig"
FROM revisions r, public.assessments a WHERE a.slug=r.slug AND i.assessment_id=a.id AND i.position=r.position;
